import pandas as pd
import numpy as np
import os
from sklearn.ensemble import RandomForestClassifier
from sklearn.multioutput import MultiOutputClassifier
from sklearn.model_selection import train_test_split
from sklearn.metrics import roc_auc_score

# Paths
INPUT_DIR = "./input"
ESSENTIAL_DIR = os.path.join(INPUT_DIR, "essential_data")
SUPPLEMENTAL_DIR = os.path.join(INPUT_DIR, "supplemental_data")
SUBMISSION_DIR = "./submission"

# Ensure submission directory exists
os.makedirs(SUBMISSION_DIR, exist_ok=True)

# Load CV folds
folds_path = os.path.join(ESSENTIAL_DIR, "CVfolds_2.txt")
folds_data = []
with open(folds_path, "r") as f:
    lines = f.readlines()

start_idx = 0
if lines and "rec_id" in lines[0]:
    start_idx = 1

for line in lines[start_idx:]:
    parts = line.strip().split(",")
    if len(parts) >= 2:
        try:
            rec_id = int(parts[0])
            fold = int(parts[1])
            folds_data.append((rec_id, fold))
        except ValueError:
            continue

folds_df = pd.DataFrame(folds_data, columns=["rec_id", "fold"])
train_ids = folds_df[folds_df["fold"] == 0]["rec_id"].values
test_ids = folds_df[folds_df["fold"] == 1]["rec_id"].values

# Load labels
labels_path = os.path.join(ESSENTIAL_DIR, "rec_labels_test_hidden.txt")
train_labels = {}
with open(labels_path, "r") as f:
    lines = f.readlines()

start_idx = 0
if lines and "rec_id" in lines[0]:
    start_idx = 1

for line in lines[start_idx:]:
    parts = line.strip().split(",")
    if not parts or not parts[0]:
        continue
    try:
        rec_id = int(parts[0])
    except ValueError:
        continue

    if len(parts) > 1 and parts[1] == "?":
        continue
    else:
        labels_vec = np.zeros(19)
        for l in parts[1:]:
            if l.strip():
                try:
                    labels_vec[int(l)] = 1
                except ValueError:
                    pass
        train_labels[rec_id] = labels_vec

# Load histogram features
hist_features_path = os.path.join(SUPPLEMENTAL_DIR, "histogram_of_segments.txt")
hist_feature_dim = 0
all_hist_features = {}

if os.path.exists(hist_features_path):
    with open(hist_features_path, "r") as f:
        lines = f.readlines()

    start_idx = 0
    if lines:
        first_part = lines[0].split(",")[0].strip()
        if not first_part.replace(".", "").replace("-", "").isdigit():
            start_idx = 1

    if len(lines) > start_idx:
        parts = lines[start_idx].strip().split(",")
        hist_feature_dim = len(parts) - 1

    for line in lines[start_idx:]:
        parts = line.strip().split(",")
        if not parts or not parts[0]:
            continue
        try:
            rec_id = int(parts[0])
        except ValueError:
            continue

        features = np.array([float(x) for x in parts[1:]], dtype=np.float32)
        if len(features) < hist_feature_dim:
            features = np.pad(
                features, (0, hist_feature_dim - len(features)), mode="constant"
            )
        all_hist_features[rec_id] = features

# Load segment features and aggregate
seg_features_path = os.path.join(SUPPLEMENTAL_DIR, "segment_features.txt")
seg_feature_dim = 38
all_seg_stats = {}

if os.path.exists(seg_features_path):
    seg_data = []
    with open(seg_features_path, "r") as f:
        lines = f.readlines()

    start_idx = 0
    if lines:
        first_part = lines[0].split(",")[0].strip()
        if not first_part.replace(".", "").replace("-", "").isdigit():
            start_idx = 1

    for line in lines[start_idx:]:
        parts = line.strip().split(",")
        if not parts or not parts[0]:
            continue
        try:
            rec_id = int(parts[0])
        except ValueError:
            continue

        if len(parts) >= 2 + seg_feature_dim:
            features = np.array(
                [float(x) for x in parts[2 : 2 + seg_feature_dim]], dtype=np.float32
            )
            seg_data.append((rec_id, features))

    rec_seg_features = {}
    for rec_id, features in seg_data:
        if rec_id not in rec_seg_features:
            rec_seg_features[rec_id] = []
        rec_seg_features[rec_id].append(features)

    for rec_id, features_list in rec_seg_features.items():
        features_array = np.array(features_list)
        stats = {}
        stats["mean"] = np.mean(features_array, axis=0)
        stats["std"] = np.std(features_array, axis=0)
        stats["min"] = np.min(features_array, axis=0)
        stats["max"] = np.max(features_array, axis=0)
        stats["median"] = np.median(features_array, axis=0)
        stats["count"] = np.array([len(features_list)], dtype=np.float32)
        all_seg_stats[rec_id] = stats


def build_features(ids, hist_features, seg_stats, hist_dim, seg_dim):
    features_list = []
    for rec_id in ids:
        feat = []
        if rec_id in hist_features:
            feat.extend(hist_features[rec_id].tolist())
        else:
            feat.extend([0.0] * hist_dim)

        if rec_id in seg_stats:
            stats = seg_stats[rec_id]
            for key in ["mean", "std", "min", "max", "median"]:
                feat.extend(stats[key].tolist())
            feat.append(stats["count"][0])
        else:
            feat.extend([0.0] * (5 * seg_dim + 1))

        features_list.append(feat)

    return np.array(features_list, dtype=np.float32)


# Build training data
X_train_full = build_features(
    train_ids, all_hist_features, all_seg_stats, hist_feature_dim, seg_feature_dim
)
y_train_full = np.array([train_labels[rec_id] for rec_id in train_ids])

# Split for validation
X_tr, X_val, y_tr, y_val = train_test_split(
    X_train_full, y_train_full, test_size=0.2, random_state=42
)

# Train model
model = MultiOutputClassifier(
    RandomForestClassifier(n_estimators=200, random_state=123, n_jobs=-1)
)
model.fit(X_tr, y_tr)

# Validate on hold-out set
y_val_pred = model.predict_proba(X_val)
val_aucs = []
for i in range(19):
    y_true = y_val[:, i]
    # y_val_pred is a list of arrays, one per output
    y_score = y_val_pred[i][:, 1]
    # Fix: Only compute AUC if both classes are present
    if len(np.unique(y_true)) > 1:
        try:
            val_aucs.append(roc_auc_score(y_true, y_score))
        except Exception:
            pass

if len(val_aucs) > 0:
    val_auc = np.mean(val_aucs)
    print(f"Validation AUC-ROC: {val_auc:.4f}")
else:
    print("Validation AUC-ROC: N/A (No valid classes for AUC calculation)")

# Build test features
X_test = build_features(
    test_ids, all_hist_features, all_seg_stats, hist_feature_dim, seg_feature_dim
)

# Predict on test set
y_test_pred = model.predict_proba(X_test)

# Create submission file
submission_data = []
for idx, rec_id in enumerate(test_ids):
    for species in range(19):
        # FIX: MultiOutputClassifier returns list of arrays indexed by species first
        prob = y_test_pred[species][idx][1]
        submission_data.append({"Id": rec_id * 100 + species, "Probability": prob})

submission_df = pd.DataFrame(submission_data)
submission_df.to_csv(os.path.join(SUBMISSION_DIR, "submission.csv"), index=False)
print(f"Submission saved with {len(submission_df)} rows")
